function escapeHtml(s){
  return String(s==null?'':s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
}
function formatDateLabel(dateStr){
  if(!dateStr)return'';
  const d=new Date(dateStr);
  if(isNaN(d))return dateStr;
  return d.toLocaleDateString('en-US',{month:'long',year:'numeric'});
}
/* ---- Rich text editor (Body field) ---- */
const RTE_ALLOWED_TAGS={P:1,BR:1,STRONG:1,B:1,EM:1,I:1,U:1,H1:1,H2:1,H3:1,BLOCKQUOTE:1,UL:1,OL:1,LI:1,A:1,IMG:1,IFRAME:1,DIV:1,HR:1,SPAN:1};
const RTE_ALLOWED_ATTRS={A:['href','target','rel'],IMG:['src','alt'],IFRAME:['src','allowfullscreen','loading','frameborder'],DIV:['class']};
const RTE_STRIP_ENTIRELY={SCRIPT:1,STYLE:1,NOSCRIPT:1,TEMPLATE:1,OBJECT:1,EMBED:1,TITLE:1,HEAD:1,META:1,LINK:1};
function sanitizeHtml(html){
  const container=document.createElement('div');
  container.innerHTML=html;
  (function clean(node){
    Array.from(node.childNodes).forEach(child=>{
      if(child.nodeType===1){
        const tag=child.tagName;
        if(RTE_STRIP_ENTIRELY[tag]){
          node.removeChild(child);
          return;
        }
        if(!RTE_ALLOWED_TAGS[tag]){
          while(child.firstChild)node.insertBefore(child.firstChild,child);
          node.removeChild(child);
          return;
        }
        const allowed=RTE_ALLOWED_ATTRS[tag]||[];
        Array.from(child.attributes).forEach(attr=>{
          if(!allowed.includes(attr.name))child.removeAttribute(attr.name);
        });
        if(tag==='A'){
          const href=child.getAttribute('href')||'';
          if(!/^https?:\/\//i.test(href)&&!/^mailto:/i.test(href))child.removeAttribute('href');
          child.setAttribute('target','_blank');
          child.setAttribute('rel','noopener noreferrer');
        }
        if(tag==='IMG'){
          const src=child.getAttribute('src')||'';
          if(!/^data:image\//i.test(src)&&!/^https?:\/\//i.test(src))child.remove();
        }
        if(tag==='IFRAME'){
          const src=child.getAttribute('src')||'';
          if(!/^https:\/\/(www\.youtube\.com\/embed\/|player\.vimeo\.com\/video\/)/i.test(src)){child.remove();return;}
        }
        if(tag==='DIV'&&child.className!=='rte-video-wrap')child.removeAttribute('class');
        clean(child);
      }else if(child.nodeType!==3){
        node.removeChild(child);
      }
    });
  })(container);
  return container.innerHTML;
}
function htmlToText(html){
  const d=document.createElement('div');
  d.innerHTML=html;
  return d.textContent||'';
}
function withDropCap(html){
  const d=document.createElement('div');
  d.innerHTML=html;
  const firstP=d.querySelector('p');
  if(firstP)firstP.classList.add('drop-cap');
  return d.innerHTML;
}
function rteExec(cmd,value){
  document.getElementById('af-body').focus();
  document.execCommand(cmd,false,value);
}
function rteFormatBlock(tag){
  rteExec('formatBlock',tag);
}
function rteInsertLink(){
  const sel=window.getSelection();
  if(!sel||sel.isCollapsed){alert('Select some text first, then click Link.');return;}
  const url=prompt('Link URL (include https://):');
  if(!url)return;
  rteExec('createLink',url);
}
function rteInsertImage(){
  const input=document.createElement('input');
  input.type='file';
  input.accept='image/*';
  input.onchange=()=>{
    const file=input.files[0];
    if(!file)return;
    resizeImage(file,700,dataUrl=>{
      rteExec('insertHTML','<img src="'+dataUrl+'" alt="">');
    },0.62);
  };
  input.click();
}
function videoUrlToEmbed(url){
  let id=null,provider=null,m;
  m=url.match(/(?:youtube\.com\/watch\?v=|youtu\.be\/|youtube\.com\/embed\/)([\w-]{11})/);
  if(m){id=m[1];provider='youtube';}
  if(!id){
    m=url.match(/vimeo\.com\/(\d+)/);
    if(m){id=m[1];provider='vimeo';}
  }
  if(!id)return null;
  const src=provider==='youtube'?('https://www.youtube.com/embed/'+id):('https://player.vimeo.com/video/'+id);
  return '<div class="rte-video-wrap" contenteditable="false"><iframe src="'+src+'" allowfullscreen loading="lazy"></iframe></div><p><br></p>';
}
function rteInsertVideo(){
  const url=prompt('Paste a YouTube or Vimeo link:');
  if(!url)return;
  const embed=videoUrlToEmbed(url);
  if(!embed){alert('Could not recognize that link. Please paste a full YouTube or Vimeo URL.');return;}
  rteExec('insertHTML',embed);
}

const SEED_ARTICLE = {"id": "seed-emmanuella", "title": "South Sudan's Lens of Hope: 25-Year-Old Journalist Emmanuella Joyce Risks Everything for Peace", "author": "Cinderella Ayebare", "authorRole": "Writer \u00b7 PJF East Africa", "authorBio": "Award-winning youth reporter and multimedia storyteller specialising in gender-responsive solutions journalism, children's rights, and grassroots GBV prevention.", "authorPhoto": "data:image/jpeg;base64,", "category": "Feature", "tag": "South Sudan", "date": "2026-06-01", "dateLabel": "June 2026", "readTime": "8 min read", "excerpt": "In South Sudan, where headlines often focus majorly on conflict, 25-year-old journalist Emmanuella Joyce is changing the lens. She does not just report on the destruction \u2014 she seeks out the hands rebuilding from it. Working with the South Sudan Broadcasting Corporation (SSBC), her work embodies the core mission of peace journalism.", "pullquote": "\"When violence strikes that close, the numbers fade, replaced by faces.\" \u2014 Emmanuella Joyce", "photo": "data:image/jpeg;base64,", "gallery": [{"src": "data:image/jpeg;base64,", "caption": "Emmanuella maintains a calm, authoritative presence during interviews \u2014 building community trust essential for responsible reporting. Photo: Ella's Archive."}, {"src": "data:image/jpeg;base64,", "caption": "Emmanuella Joyce at work in a rural community in South Sudan. Photo credit: Ella's Archive."}], "status": "published", "createdBy": "admin", "createdByName": "Admin", "featured": true, "body": "<p>In South Sudan, where headlines often focus majorly on conflict, 25-year-old journalist Emmanuella Joyce is changing the lens. She does not just report on the destruction; she seeks out the hands rebuilding from it. However, while Emmanuella is fortunate to possess safety training and ethical knowledge, hundreds of younger South Sudanese reporters lack these vital tools. To survive on the frontlines, this new generation urgently requires specialist, conflict-sensitive training.</p><p>Working with the South Sudan Broadcasting Corporation (SSBC), Emmanuella does not merely catalogue destruction; she seeks out the hands rebuilding from the ashes. Her work embodies the core mission of peace journalism: uncovering underreported crises while highlighting human resilience, local solutions, and an unyielding professionalism in the face of violence.</p><h3>Ambushes, roadblocks, and raw experience</h3><p>The path of a frontline reporter in South Sudan is fraught with a chilling level of intrigue and unpredictability. For Emmanuella, the physical dangers of the trail are not abstract concepts; they are lived experiences. Having narrowly escaped two deadly attacks that instantly transformed vibrant, bustling villages into landscapes of sudden darkness and mourning, her notebook has evolved from a simple professional tool into a living archive of survival.</p><h3>The highway of deception: weaponising innocence</h3><p>Among the most harrowing dimensions of this modern conflict is the deceptive exploitation of human empathy along dangerous transit corridors. Ambush teams now employ a devastating tactic, placing young children along highways to simulate extreme distress. When unsuspecting travellers and journalists stop to offer humanitarian aid, attackers emerge from the bush to rob, abduct, or kill. This weaponisation of innocence not only poses an immediate physical threat to reporters on assignment, but also risks inflaming community anger and distrust toward legitimate aid workers and media personnel operating in the region.</p><h3>The shield of truth: navigating volatile zones</h3><p>Navigating volatile zones warped by rumours and weaponised disinformation requires more than raw courage; it demands flawless professional execution. To survive, Emmanuella relies on her rigorous training in media ethics and conflict-sensitive reporting. In areas where misinformation can instantly ignite fresh violence, strict factual verification acts as her primary shield. By reporting accurately and treating highly vulnerable populations with deep respect, she builds an ironclad community trust that few other reporters can match.</p><h3>Invisible burden: trauma and duty</h3><p>Processing the invisible burden of frontline reporting is a heavy trial for this youngest generation of journalists, bringing sleepless nights and acute anxiety. Yet, Emmanuella's resilience is forged in the realisation that admitting emotional exhaustion does not dilute her professional duty; rather, it deepens it.</p><blockquote>\"When violence strikes that close, the numbers fade, replaced by faces.\" \u2014 Emmanuella Joyce</blockquote><h3>Restorative hope: spotlighting community healing</h3><p>Peace journalism demands a deliberate, radical shift away from traditional war reportage. Rather than simply counting casualties, Emmanuella uses her platform at the SSBC to illuminate the quiet architecture of community healing and structural restoration. Her coverage systematically spotlights grassroots reconciliation meetings that bridge deep-seated tribal fractures, youth-led peace initiatives designed to curb unemployment and radicalisation, and women taking the lead in community building efforts.</p><h3>A new narrative forged by dialogue</h3><p>From the perspective of a young female journalist shaping national media, sustainable peace cannot be built solely on elite political handshakes. It requires addressing everyday struggles and unaddressed trauma. By creating media spaces dedicated to genuine dialogue, this new generation aims to replace polarisation with tangible, local solutions. Driven by a profound sense of calling, Emmanuella remains resolute on the frontlines.</p><blockquote>\"Silence becomes far more terrifying than the physical risks of the trail.\" \u2014 Emmanuella Joyce</blockquote><p><strong>Editorial Note:</strong> Female journalists in South Sudan face immense, gender-specific risks, including sexual harassment and systemic exclusion, compounded by the constant threats of frontline reporting. The international community and media networks must prioritize specialized safety training, protection mechanisms, and institutional backing to safeguard these brave women, ensuring that the vital stories of community reconciliation and local resilience continue to be told.</p>"};

async function seedIfEmptyForAdmin(){
  try{
    const settingsRef=db.collection('settings').doc('site');
    const settingsSnap=await settingsRef.get();
    if(!settingsSnap.exists){
      await settingsRef.set({
        heroEyebrow:'East Africa · Founded 2014',
        heroHeadline:'Promoting Peace Through <em>Responsible Journalism</em> Across East Africa',
        heroSub:'Shifting narratives. Building peace. Amplifying grassroots voices in communities where stories matter most.',
        statFounded:'2014',statCountries:'7',statPartnerships:'50+',
        impactTrained:'800',impactMedia:'60',impactCountries:'7',impactYears:'12',
        articlesSeeded:true
      });
      const seed=Object.assign({},SEED_ARTICLE);
      delete seed.id;
      seed.createdBy=currentProfile.uid;
      seed.createdByName=currentProfile.name||currentProfile.email;
      seed.updatedAt=new Date().toISOString();
      await db.collection('articles').add(seed);
    }else if(!settingsSnap.data().articlesSeeded){
      // Site already existed before this flag was introduced — mark it seeded
      // without re-adding the demo article, so deleted articles stay deleted.
      await settingsRef.set({articlesSeeded:true},{merge:true});
    }
  }catch(ex){
    console.error('Seeding failed:',ex);
  }
}

function applySettingsToPage(){
  const s=settingsCache||{};
  const eyebrow=document.querySelector('.hero-eyebrow');if(eyebrow&&s.heroEyebrow)eyebrow.textContent=s.heroEyebrow;
  const hl=document.querySelector('.hero-headline');if(hl&&s.heroHeadline)hl.innerHTML=s.heroHeadline;
  const sub=document.querySelector('.hero-sub');if(sub&&s.heroSub)sub.textContent=s.heroSub;
  const statNums=document.querySelectorAll('#about .stat-num');
  if(statNums[0]&&s.statFounded)statNums[0].textContent=s.statFounded;
  if(statNums[1]&&s.statCountries)statNums[1].textContent=s.statCountries;
  if(statNums[2]&&s.statPartnerships)statNums[2].textContent=s.statPartnerships;
  const impactNums=document.querySelectorAll('#impact-bar .impact-num');
  const setImpact=(el,val)=>{
    if(!el||val===undefined||val==='')return;
    const num=parseInt(String(val).replace(/\D/g,''))||0;
    el.dataset.target=num;
    if(el.dataset.animated)el.textContent=num+'+';
  };
  setImpact(impactNums[0],s.impactTrained);
  setImpact(impactNums[1],s.impactMedia);
  setImpact(impactNums[2],s.impactCountries);
  setImpact(impactNums[3],s.impactYears);
}

function getArticleById(id){
  const arts=articlesCache;
  if(id)return arts.find(a=>a.id===id);
  const published=arts.filter(a=>a.status==='published').sort((a,b)=>new Date(b.date)-new Date(a.date));
  return published[0];
}

function renderNewsroom(){
  const gridEl=document.getElementById('newsroomGrid');
  if(!gridEl)return;
  const arts=articlesCache.filter(a=>a.status==='published').sort((a,b)=>new Date(b.date)-new Date(a.date));
  if(arts.length===0){
    gridEl.innerHTML='<div class="newsroom-empty">No published stories yet. Check back soon.</div>';
    return;
  }
  gridEl.innerHTML=arts.map(a=>{
    const excerpt=(a.excerpt||'');
    const short=excerpt.length>120?excerpt.slice(0,120)+'…':excerpt;
    return `
    <a href="#article-full:${a.id}" class="news-card">
      <div class="news-card-photo">${a.photo?`<img src="${a.photo}" alt="${escapeHtml(a.title)}">`:''}</div>
      <div class="news-card-body">
        <span class="article-category" style="align-self:flex-start;">${escapeHtml(a.category||'Story')}</span>
        <div class="news-card-title">${escapeHtml(a.title)}</div>
        <div class="news-card-excerpt">${escapeHtml(short)}</div>
        <div class="news-card-byline">By ${escapeHtml(a.author)} · ${escapeHtml(a.dateLabel||formatDateLabel(a.date))}</div>
        <span class="news-card-link">View Full Story →</span>
      </div>
    </a>`;
  }).join('');
}

