/* ---- Auth ---- */
async function handleAdminLogin(e){
  e.preventDefault();
  const email=document.getElementById('loginEmail').value.trim();
  const password=document.getElementById('loginPassword').value;
  const err=document.getElementById('loginError');
  const btn=document.getElementById('adminLoginForm').querySelector('button[type=submit]');
  btn.disabled=true;
  try{
    await auth.signInWithEmailAndPassword(email,password);
    err.style.display='none';
    document.getElementById('adminLoginForm').reset();
  }catch(ex){
    err.textContent='Invalid email or password.';
    err.style.display='block';
  }
  btn.disabled=false;
  return false;
}
function handleAdminLogout(){
  auth.signOut();
}
function checkSession(){
  const outEl=document.getElementById('adminLoggedOut');
  const inEl=document.getElementById('adminLoggedIn');
  if(!outEl||!inEl)return;
  if(currentProfile){
    outEl.style.display='none';
    inEl.style.display='block';
    document.getElementById('whoamiName').textContent=currentProfile.name||currentProfile.email;
    document.getElementById('whoamiRole').textContent=currentProfile.role;
    applyRoleVisibility();
    const activeTab=document.querySelector('.admin-tab.active');
    switchAdminTab(activeTab?activeTab.dataset.tab:'articles');
  }else{
    outEl.style.display='block';
    inEl.style.display='none';
  }
}
function applyRoleVisibility(){
  if(!currentProfile)return;
  const isAdmin=currentProfile.role==='admin';
  document.querySelectorAll('.admin-only').forEach(el=>{el.style.display=isAdmin?'':'none';});
  const publishedOpt=document.querySelector('#af-status option[value="published"]');
  if(publishedOpt)publishedOpt.style.display=isAdmin?'':'none';
}
function switchAdminTab(tab){
  if(!currentProfile)return;
  if((tab==='settings'||tab==='users')&&currentProfile.role!=='admin')tab='articles';
  if(!tab)tab='articles';
  document.querySelectorAll('.admin-tab').forEach(t=>t.classList.toggle('active',t.dataset.tab===tab));
  document.querySelectorAll('.admin-panel').forEach(p=>p.classList.toggle('active',p.id==='panel-'+tab));
  if(tab==='articles')renderAdminArticleList();
  if(tab==='settings')loadSettingsIntoForm();
  if(tab==='users')renderUserList();
}
function getSecondaryAuth(){
  let secondaryApp=firebase.apps.find(a=>a.name==='Secondary');
  if(!secondaryApp)secondaryApp=firebase.initializeApp(firebaseConfig,'Secondary');
  return secondaryApp.auth();
}
auth.onAuthStateChanged(async(user)=>{
  if(unsubPublished){unsubPublished();unsubPublished=null;}
  if(unsubMine){unsubMine();unsubMine=null;}
  if(unsubSettings){unsubSettings();unsubSettings=null;}
  mineArticles=[];
  if(user){
    let profileData={role:'editor',name:user.email,email:user.email};
    try{
      const snap=await db.collection('profiles').doc(user.uid).get();
      if(snap.exists)profileData=Object.assign({},snap.data(),{email:user.email});
    }catch(ex){console.error('Could not load profile:',ex);}
    currentProfile={uid:user.uid,email:user.email,name:profileData.name,role:profileData.role};
    if(currentProfile.role==='admin')await seedIfEmptyForAdmin();
  }else{
    currentProfile=null;
  }

  // Published articles are readable by everyone (logged in or not) — a query
  // Firestore can prove is safe because the where() clause matches the rule.
  unsubPublished=db.collection('articles').where('status','==','published').onSnapshot(snap=>{
    publishedArticles=snap.docs.map(d=>Object.assign({id:d.id},d.data()));
    rebuildArticlesCache();
  },err=>console.error('published articles listener error:',err));

  // Drafts/pending are only visible to their owner (or everything, for admin).
  if(currentProfile&&currentProfile.role==='admin'){
    unsubMine=db.collection('articles').onSnapshot(snap=>{
      mineArticles=snap.docs.map(d=>Object.assign({id:d.id},d.data()));
      rebuildArticlesCache();
    },err=>console.error('admin articles listener error:',err));
  }else if(currentProfile){
    unsubMine=db.collection('articles').where('createdBy','==',currentProfile.uid).onSnapshot(snap=>{
      mineArticles=snap.docs.map(d=>Object.assign({id:d.id},d.data()));
      rebuildArticlesCache();
    },err=>console.error('own articles listener error:',err));
  }

  unsubSettings=db.collection('settings').doc('site').onSnapshot(snap=>{
    settingsCache=snap.exists?snap.data():{};
    applySettingsToPage();
    loadSettingsIntoForm();
  },err=>console.error('settings listener error:',err));
  checkSession();
});

/* ---- Articles admin ---- */
let pendingPhotoData=null;
function resizeImage(file,maxWidth,cb,quality){
  quality=quality||0.7;
  const reader=new FileReader();
  reader.onload=function(ev){
    const img=new Image();
    img.onload=function(){
      let w=img.width,h=img.height;
      if(w>maxWidth){h=Math.round(h*maxWidth/w);w=maxWidth;}
      const canvas=document.createElement('canvas');
      canvas.width=w;canvas.height=h;
      canvas.getContext('2d').drawImage(img,0,0,w,h);
      cb(canvas.toDataURL('image/jpeg',quality));
    };
    img.src=ev.target.result;
  };
  reader.readAsDataURL(file);
}
document.addEventListener('change',function(e){
  if(e.target&&e.target.id==='af-photo'){
    const file=e.target.files[0];
    if(!file)return;
    resizeImage(file,900,dataUrl=>{pendingPhotoData=dataUrl;},0.68);
  }
});
function rtePasteOrDrop(e,dataTransfer){
  e.preventDefault();
  const html=dataTransfer.getData('text/html');
  if(html){
    document.execCommand('insertHTML',false,sanitizeHtml(html));
  }else{
    const text=dataTransfer.getData('text/plain');
    document.execCommand('insertText',false,text);
  }
}
document.addEventListener('paste',function(e){
  if(e.target&&e.target.id==='af-body'&&e.clipboardData){
    rtePasteOrDrop(e,e.clipboardData);
  }
});
document.addEventListener('drop',function(e){
  if(e.target&&e.target.closest&&e.target.closest('#af-body')&&e.dataTransfer){
    rtePasteOrDrop(e,e.dataTransfer);
  }
});

function renderAdminArticleList(){
  const listEl=document.getElementById('adminArticleList');
  if(!currentProfile||!listEl)return;
  let arts=articlesCache.slice().sort((a,b)=>(b.updatedAt||b.date||'').localeCompare(a.updatedAt||a.date||''));
  if(currentProfile.role!=='admin')arts=arts.filter(a=>a.createdBy===currentProfile.uid);
  if(arts.length===0){
    listEl.innerHTML='<p style="color:var(--gray-mid);font-size:14px;">No articles yet. Create one from the "New Article" tab.</p>';
    return;
  }
  listEl.innerHTML=arts.map(a=>{
    const isOwner=a.createdBy===currentProfile.uid;
    const isAdmin=currentProfile.role==='admin';
    const canPublish=isAdmin&&a.status!=='published';
    const canUnpublish=isAdmin&&a.status==='published';
    const canDelete=isAdmin||(isOwner&&a.status!=='published');
    const canEdit=isAdmin||isOwner;
    return `
    <div class="article-row">
      <div>
        <div class="article-row-title">${escapeHtml(a.title)}<span class="status-badge ${a.status}">${a.status}</span></div>
        <div class="article-row-meta">By ${escapeHtml(a.author)}${a.createdByName?' · added by '+escapeHtml(a.createdByName):''} · ${escapeHtml(a.dateLabel||formatDateLabel(a.date))}</div>
      </div>
      <div class="article-row-actions">
        ${canEdit?`<button type="button" class="btn-sm" onclick="loadArticleIntoForm('${a.id}')">Edit</button>`:''}
        ${canPublish?`<button type="button" class="btn-sm gold" onclick="setArticleStatus('${a.id}','published')">Publish</button>`:''}
        ${canUnpublish?`<button type="button" class="btn-sm" onclick="setArticleStatus('${a.id}','draft')">Unpublish</button>`:''}
        <button type="button" class="btn-sm" onclick="previewArticle('${a.id}')">Preview</button>
        ${canDelete?`<button type="button" class="btn-sm danger" onclick="deleteArticle('${a.id}')">Delete</button>`:''}
      </div>
    </div>`;
  }).join('');
}
function previewArticle(id){location.hash='#article-full:'+id;}
async function setArticleStatus(id,status){
  try{
    await db.collection('articles').doc(id).update({status,updatedAt:new Date().toISOString()});
  }catch(ex){
    alert('Could not update the article: '+ex.message);
  }
}
async function deleteArticle(id){
  if(!confirm('Delete this article? This cannot be undone.'))return;
  try{
    await db.collection('articles').doc(id).delete();
  }catch(ex){
    alert('Could not delete the article: '+ex.message);
  }
}
function loadArticleIntoForm(id){
  const a=articlesCache.find(x=>x.id===id);
  if(!a)return;
  document.getElementById('af-id').value=a.id;
  document.getElementById('af-title').value=a.title||'';
  document.getElementById('af-author').value=a.author||'';
  document.getElementById('af-category').value=a.category||'';
  document.getElementById('af-tag').value=a.tag||'';
  document.getElementById('af-excerpt').value=a.excerpt||'';
  document.getElementById('af-body').innerHTML=a.body||'';
  document.getElementById('af-status').value=a.status||'draft';
  pendingPhotoData=a.photo||null;
  document.getElementById('articleFormTitle').textContent='Edit Article';
  document.getElementById('articleFormError').style.display='none';
  switchAdminTab('new');
}
function resetArticleForm(){
  document.getElementById('articleForm').reset();
  document.getElementById('af-id').value='';
  document.getElementById('af-body').innerHTML='';
  document.getElementById('articleFormTitle').textContent='New Article';
  document.getElementById('articleFormError').style.display='none';
  pendingPhotoData=null;
  applyRoleVisibility();
}
async function handleArticleSubmit(e){
  e.preventDefault();
  if(!currentProfile)return false;
  const id=document.getElementById('af-id').value;
  let status=document.getElementById('af-status').value;
  if(currentProfile.role!=='admin'&&status==='published')status='pending';
  const title=document.getElementById('af-title').value.trim();
  const body=sanitizeHtml(document.getElementById('af-body').innerHTML);
  const bodyText=htmlToText(body).trim();
  const err=document.getElementById('articleFormError');
  if(!title||!bodyText){
    err.textContent='Title and body are required.';
    err.style.display='block';
    return false;
  }
  const now=new Date();
  const docData={
    title,
    author:document.getElementById('af-author').value.trim(),
    category:document.getElementById('af-category').value.trim(),
    tag:document.getElementById('af-tag').value.trim(),
    excerpt:document.getElementById('af-excerpt').value.trim(),
    body,status,
    updatedAt:now.toISOString()
  };
  if(pendingPhotoData)docData.photo=pendingPhotoData;

  const approxSize=new Blob([JSON.stringify(docData)]).size;
  if(approxSize>900*1024){
    err.textContent='This article is too large to save (photos/body too big — Firestore caps each article at 1MB). Try a smaller photo or fewer inline images.';
    err.style.display='block';
    return false;
  }
  err.style.display='none';

  const submitBtn=document.getElementById('articleForm').querySelector('button[type=submit]');
  submitBtn.disabled=true;
  try{
    if(id){
      const existing=articlesCache.find(x=>x.id===id);
      if(!existing)throw new Error('Article not found.');
      if(currentProfile.role!=='admin'&&existing.createdBy!==currentProfile.uid)throw new Error('Not allowed.');
      await db.collection('articles').doc(id).update(docData);
    }else{
      docData.date=now.toISOString().slice(0,10);
      docData.dateLabel=now.toLocaleDateString('en-US',{month:'long',year:'numeric'});
      docData.readTime=Math.max(3,Math.round(bodyText.split(/\s+/).length/200))+' min read';
      docData.createdBy=currentProfile.uid;
      docData.createdByName=currentProfile.name||currentProfile.email;
      if(!docData.photo)docData.photo=null;
      await db.collection('articles').add(docData);
    }
    resetArticleForm();
    switchAdminTab('articles');
  }catch(ex){
    err.textContent='Could not save: '+ex.message;
    err.style.display='block';
  }
  submitBtn.disabled=false;
  return false;
}

