/* DASHBOARD ROUTING */
const pages=document.querySelectorAll('.page');
const sidebarLinks=document.querySelectorAll('.sidebar-link');
const sidebarEl=document.getElementById('sidebar');
const sidebarOverlay=document.getElementById('sidebarOverlay');
const sidebarToggle=document.getElementById('sidebarToggle');
const dashboardMain=document.getElementById('dashboardMain');

function openSidebar(){sidebarEl.classList.add('open');sidebarOverlay.classList.add('open');sidebarToggle.setAttribute('aria-expanded','true');}
function closeSidebar(){sidebarEl.classList.remove('open');sidebarOverlay.classList.remove('open');sidebarToggle.setAttribute('aria-expanded','false');}
sidebarToggle.addEventListener('click',()=>{sidebarEl.classList.contains('open')?closeSidebar():openSidebar();});
sidebarOverlay.addEventListener('click',closeSidebar);

function showRoute(rawKey){
  let key=rawKey;
  let subId=null;
  if(key && key.includes(':')){
    const parts=key.split(':');
    key=parts[0];
    subId=parts.slice(1).join(':');
  }
  if(!key)key='hero';
  let matched=false;
  pages.forEach(p=>{
    const routeKey=p.dataset.route||p.id;
    const isMatch=routeKey===key;
    p.classList.toggle('active',isMatch);
    if(isMatch)matched=true;
  });
  if(!matched){
    key='hero';
    pages.forEach(p=>p.classList.toggle('active',(p.dataset.route||p.id)==='hero'));
  }
  sidebarLinks.forEach(a=>a.classList.toggle('active',a.getAttribute('href')==='#'+key));
  dashboardMain.scrollTop=0;
  window.scrollTo(0,0);
  closeSidebar();
  if(key==='newsroom')renderNewsroom();
  if(key==='article-full'){currentArticleSubId=subId;renderArticleFull(subId);}
  if(key==='admin')checkSession();
}

function routeFromHash(){showRoute(location.hash.slice(1));}

document.querySelectorAll('a[href^="#"]').forEach(a=>{
  a.addEventListener('click',e=>{
    const href=a.getAttribute('href');
    if(href.length>1){
      e.preventDefault();
      if(location.hash===href){routeFromHash();}else{location.hash=href;}
    }
  });
});

window.addEventListener('hashchange',routeFromHash);
routeFromHash();